:root {
    --coffee: #4a2c20;
    --coffee-dark: #2f1b14;
    --gold: #c58b3a;
    --cream: #f7f1e8;
    --soft: #fbf8f3;
    --ink: #202020;
    --muted: #6b6b6b;
    --white: #ffffff;
    --danger: #a33a3a;
    --success: #2d6a4f;
    --border: #e5ded5;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
    margin: 0;
    color: var(--ink);
    background: var(--white);
    font-family: Arial, Helvetica, sans-serif;
    line-height: 1.6;
}
a { color: inherit; text-decoration: none; }
img { display: block; width: 100%; }
.container { width: min(1120px, 90%); margin: 0 auto; }
.narrow { max-width: 760px; }

.navbar {
    position: sticky;
    top: 0;
    z-index: 20;
    background: rgba(255, 255, 255, .96);
    border-bottom: 1px solid var(--border);
}
.nav-inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-height: 72px;
    gap: 24px;
}
.brand { color: var(--coffee-dark); font-weight: 800; }
nav { display: flex; align-items: center; gap: 20px; }
nav a:hover { color: var(--gold); }

.hero {
    padding: 96px 0;
    background: linear-gradient(135deg, var(--cream), #fff 60%);
}
.hero-grid {
    display: grid;
    grid-template-columns: 1.5fr .8fr;
    gap: 64px;
    align-items: center;
}
h1, h2, h3 { color: var(--coffee-dark); line-height: 1.15; }
h1 { margin: 12px 0 20px; font-size: clamp(2.4rem, 6vw, 4.8rem); }
h2 { margin: 10px 0 24px; font-size: clamp(1.9rem, 4vw, 3rem); }
h3 { margin: 0 0 10px; }
.eyebrow {
    color: var(--gold);
    font-size: .78rem;
    font-weight: 800;
    letter-spacing: .14em;
    text-transform: uppercase;
}
.hero-card {
    padding: 28px;
    color: var(--white);
    background: var(--coffee);
    border-radius: 24px;
    box-shadow: 0 20px 50px rgba(47, 27, 20, .18);
}
.hero-card p { padding: 12px 0; border-bottom: 1px solid #ffffff33; }

.section { padding: 80px 0; }
.section-soft { background: var(--soft); }
.features, .product-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
}
.features article, .product-card {
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: 18px;
    overflow: hidden;
    box-shadow: 0 10px 30px rgba(47, 27, 20, .06);
}
.features article { padding: 26px; }
.product-card img { height: 210px; object-fit: cover; background: var(--cream); }
.product-body { padding: 22px; }
.product-body strong { color: var(--coffee); font-size: 1.1rem; }
.contact { color: var(--white); background: var(--coffee-dark); }
.contact h2 { color: var(--white); }
.footer { padding: 24px 0; color: #eaded5; background: #21120d; }

.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    padding: 11px 18px;
    color: var(--white);
    background: var(--coffee);
    border: 0;
    border-radius: 10px;
    cursor: pointer;
    font: inherit;
    font-weight: 700;
}
.btn:hover { background: var(--coffee-dark); }
.btn-small { padding: 8px 12px; font-size: .86rem; }
.btn-secondary { color: var(--coffee); background: var(--cream); }
.btn-edit { background: #8a6426; }
.btn-danger { background: var(--danger); }

.admin-page { min-height: 100vh; padding: 56px 0; background: var(--soft); }
.admin-container { max-width: 760px; }
.admin-container.wide { max-width: 1120px; }
.page-heading {
    display: flex;
    justify-content: space-between;
    align-items: end;
    gap: 20px;
    margin-bottom: 24px;
}
.page-heading h1 { margin: 6px 0 0; font-size: 2.4rem; }
.heading-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.form-card, .table-card {
    padding: 26px;
    background: var(--white);
    border: 1px solid var(--border);
    border-radius: 16px;
    box-shadow: 0 12px 32px rgba(47, 27, 20, .06);
}
.form-group { margin-bottom: 18px; }
.form-group label { display: block; margin-bottom: 6px; font-weight: 700; }
.form-control {
    width: 100%;
    padding: 11px 12px;
    border: 1px solid #cfc6bc;
    border-radius: 9px;
    font: inherit;
}
.form-control:focus { outline: 2px solid #c58b3a55; border-color: var(--gold); }
.is-invalid { border-color: var(--danger); }
.error { display: block; margin-top: 5px; color: var(--danger); }
.form-actions { display: flex; gap: 10px; margin-top: 24px; }
.alert-success {
    margin-bottom: 18px;
    padding: 12px 16px;
    color: var(--success);
    background: #eaf4ed;
    border: 1px solid #bddbc8;
    border-radius: 10px;
}
table { width: 100%; border-collapse: collapse; }
th, td { padding: 13px 12px; border-bottom: 1px solid var(--border); text-align: left; }
th { color: var(--white); background: var(--coffee); }
td small { display: block; color: var(--muted); }
.actions { display: flex; gap: 8px; align-items: center; }
.empty-state {
    grid-column: 1 / -1;
    padding: 28px;
    text-align: center;
    color: var(--muted);
    background: var(--cream);
    border-radius: 14px;
}

@media (max-width: 800px) {
    .nav-inner, nav, .page-heading { align-items: flex-start; }
    .nav-inner, .page-heading { flex-direction: column; padding: 16px 0; }
    nav { flex-wrap: wrap; gap: 12px; }
    .hero-grid, .features, .product-grid { grid-template-columns: 1fr; }
    .hero { padding: 64px 0; }
    .section { padding: 56px 0; }
    .table-card { overflow-x: auto; }
}
